# p6 (E10.28): CMRR of Fig 10.48 bipolar pair, R_C / R_C+dR_C loads, tail = Q3 degenerated by R1
import sympy as sp
gm, gm3, rpi, rpi3, ro3, R1, RC, dRC, beta = sp.symbols('g_m g_m3 r_pi r_pi3 r_O3 R_1 R_C DeltaR_C beta', positive=True)
vin1, vin2, vp, ve3, vx, ix, vo1, vo2 = sp.symbols('v_in1 v_in2 v_P v_e3 v_x i_x v_o1 v_o2')

# 1) R_out3: test source v_x at Q3 collector, base grounded (V_b AC ground)
v_pi3 = -ve3
eqs = [sp.Eq(ix, gm3*v_pi3 + (vx-ve3)/ro3),                # current into collector
       sp.Eq(ix, ve3/R1 + ve3/rpi3)]                        # current leaving emitter node (R1 and rpi3 to ground)
s = sp.solve(eqs, [ix, ve3], dict=True)[0]
Rout3 = sp.simplify(vx/s[ix])
Rp = R1*rpi3/(R1+rpi3)
target_R = (1+gm3*Rp)*ro3 + Rp
print('Rout3 =', Rout3)
print('Rout3 - [(1+gm3(R1||rpi3))ro3 + R1||rpi3] =', sp.simplify(Rout3-target_R))
Rt = sp.Symbol('R_out3', positive=True)

# 2) full pair, Q1,Q2 with gm, rpi (V_A=inf), tail impedance Rt at P
def solve_pair(v1, v2):
    ib1 = (v1-vp)/rpi; ib2 = (v2-vp)/rpi
    ic1 = gm*(v1-vp); ic2 = gm*(v2-vp)
    sol = sp.solve([sp.Eq(ib1+ic1+ib2+ic2, vp/Rt)], [vp], dict=True)[0]
    o1 = (-RC*ic1).subs(sol); o2 = (-(RC+dRC)*ic2).subs(sol)
    return sp.simplify(o1-o2)
vcm = sp.Symbol('v_cm'); vd = sp.Symbol('v_d')
A_cmdm = sp.simplify(solve_pair(vcm, vcm)/vcm)
A_dm   = sp.simplify(solve_pair(vd/2, -vd/2)/vd)
print('A_CM-DM (exact, with rpi) =', sp.factor(A_cmdm))
print('A_DM (exact) =', sp.factor(A_dm))
# beta->inf (rpi = beta/gm)
A_cmdm_b = sp.limit(A_cmdm.subs(rpi, beta/gm), beta, sp.oo)
A_dm_b = sp.limit(A_dm.subs(rpi, beta/gm), beta, sp.oo)
print('beta->inf: |A_CM-DM| =', sp.simplify(A_cmdm_b), ' minus dRC/(1/gm+2Rout3):', sp.simplify(A_cmdm_b - dRC/(1/gm+2*Rt)))
print('beta->inf: |A_DM| =', sp.simplify(-A_dm_b), '; dRC->0:', sp.limit(-A_dm_b, dRC, 0))

CMRR_exact = sp.simplify(-A_dm_b/A_cmdm_b)
print('CMRR (keeping dRC/2 in A_DM) =', sp.factor(CMRR_exact))
CMRR = sp.simplify(-sp.limit(A_dm_b, dRC, 0)/A_cmdm_b)
target = gm*RC*(1/gm + 2*Rt)/dRC
print('CMRR (A_DM = gm R_C) =', CMRR, '; minus gm R_C(1/gm+2Rout3)/dRC =', sp.simplify(CMRR-target))
print('  = R_C(1+2 gm Rout3)/dRC check:', sp.simplify(CMRR - RC*(1+2*gm*Rt)/dRC))
full = target.subs(Rt, target_R)
print('CMRR full =', full)
# without "+ R1||rpi3" term (alt form), ratio -> 1 as ro3 -> inf
alt = target.subs(Rt, (1+gm3*Rp)*ro3)
print('limit ro3->oo of full/alt =', sp.limit(full/alt, ro3, sp.oo))
# 2 Rout3 >> 1/gm limit
print('limit Rout3->oo of CMRR/(2 gm R_C Rout3/dRC) =', sp.limit(CMRR/(2*gm*RC*Rt/dRC), Rt, sp.oo))
